CREATE POLICY receipts_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='payment-receipts' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','pdf')); CREATE POLICY receipts_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='payment-receipts' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin'))); CREATE POLICY receipts_remove_unsubmitted ON storage.objects FOR DELETE TO authenticated USING(bucket_id='payment-receipts' AND (storage.foldername(name))[1]=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.orders WHERE receipt_path=name));
CREATE FUNCTION public.lms_manage_access(p_id uuid,p_expires timestamptz,p_revoke boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF NOT p_revoke AND p_expires<=now() THEN RAISE EXCEPTION 'Future expiry required'; END IF; UPDATE public.enrollments SET expires_at=CASE WHEN p_revoke THEN expires_at ELSE p_expires END,revoked_at=CASE WHEN p_revoke THEN now() ELSE NULL END WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Enrollment not found'; END IF; INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),CASE WHEN p_revoke THEN 'access.revoked' ELSE 'access.updated' END,p_id::text); END $$; REVOKE ALL ON FUNCTION public.lms_manage_access(uuid,timestamptz,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_manage_access(uuid,timestamptz,boolean) TO authenticated;
CREATE FUNCTION public.lms_issue_code(p_course uuid,p_student uuid,p_hash text,p_expires timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF length(p_hash)<>64 OR p_expires<=now() THEN RAISE EXCEPTION 'Valid code expiry required'; END IF; INSERT INTO public.redeem_codes(course_id,assigned_to,code_hash,expires_at) VALUES(p_course,p_student,p_hash,p_expires) RETURNING id INTO result; INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),'code.issued',result::text); RETURN result; END $$; REVOKE ALL ON FUNCTION public.lms_issue_code(uuid,uuid,text,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_issue_code(uuid,uuid,text,timestamptz) TO authenticated;
CREATE FUNCTION public.lms_revoke_code(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; UPDATE public.redeem_codes SET revoked_at=now() WHERE id=p_id AND redeemed_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Code not found or already used'; END IF; INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),'code.revoked',p_id::text); END $$; REVOKE ALL ON FUNCTION public.lms_revoke_code(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_revoke_code(uuid) TO authenticated;